2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `mount_setup_existing_unit()` function dropping the `MOUNT_PROC_JUST_MOUNTED` flag from units when it should have been preserved. This occurred due to an incorrect condition that did not account for the scenario where the flag was already set, leading to unintended behavior in the mount unit's state management.

        Commit message:
        core/mount: make mount_setup_existing_unit() not drop
 MOUNT_PROC_JUST_MOUNTED flag from units

This fixes a bug introduced by ec88d1ea0591beccab97d9096fd3fd7b09bc823c.

Fixes #11362.  

        Patch:

 static int mount_setup_existing_unit(
                 Unit *u,
                 const char *what,
                 const char *where,
                 const char *options,
                 const char *fstype,
                 MountProcFlags *ret_flags) {

         MountProcFlags flags = MOUNT_PROC_IS_MOUNTED;
         int r;

         assert(u);
         assert(flags);

         if (!MOUNT(u)->where) {
                 MOUNT(u)->where = strdup(where);
                 if (!MOUNT(u)->where)
                         return -ENOMEM;
         }

         r = update_parameters_proc_self_mount_info(MOUNT(u), what, options, fstype);
         if (r < 0)
                 return r;
         if (r > 0)
                 flags |= MOUNT_PROC_JUST_CHANGED;

-        if (!MOUNT(u)->from_proc_self_mountinfo) {
+        if (!MOUNT(u)->from_proc_self_mountinfo || FLAGS_SET(MOUNT(u)->proc_flags, MOUNT_PROC_JUST_MOUNTED))
                 flags |= MOUNT_PROC_JUST_MOUNTED;
-                MOUNT(u)->from_proc_self_mountinfo = true;
-        }
+
+        MOUNT(u)->from_proc_self_mountinfo = true;

         if (IN_SET(u->load_state, UNIT_NOT_FOUND, UNIT_BAD_SETTING, UNIT_ERROR)) {
                 /* The unit was previously not found or otherwise not loaded. Now that the unit shows up in
                  * /proc/self/mountinfo we should reconsider it this, hence set it to UNIT_LOADED. */
                 u->load_state = UNIT_LOADED;
                 u->load_error = 0;

                 flags |= MOUNT_PROC_JUST_CHANGED;
         }

         if (FLAGS_SET(flags, MOUNT_PROC_JUST_CHANGED)) {
                 /* If things changed, then make sure that all deps are regenerated. Let's
                  * first remove all automatic deps, and then add in the new ones. */

                 unit_remove_dependencies(u, UNIT_DEPENDENCY_MOUNTINFO_IMPLICIT);

                 r = mount_add_extras(MOUNT(u));
                 if (r < 0)
                         return r;
         }

         *ret_flags = flags;
         return 0;
 }



